def _round_ratio(numerator, denominator, mode):
    mode = mode if mode in _ROUNDING else 'floor'
    quotient, remainder = divmod(numerator, denominator)

    if mode in ('ceil', 'ceiling'):
        return quotient + (1 if remainder else 0)
    if mode == 'down':
        return quotient if numerator >= 0 or not remainder else quotient + 1
    if mode == 'half_up':
        return quotient + (1 if remainder * 2 >= denominator else 0)
    if mode == 'half_even':
